// src/components/Dashboard.jsx
import React, { useState } from "react";

const Dashboard = () => {
  const [activeSection, setActiveSection] = useState("accueil");
  const [selectedEntreprise, setSelectedEntreprise] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [showAddEntrepriseModal, setShowAddEntrepriseModal] = useState(false);
  const [selectedDocument, setSelectedDocument] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [addEntrepriseData, setAddEntrepriseData] = useState({
    nom: "",
    siret: "",
    telephone: "",
    email: "",
    nomRepresentant: "",
    prenomRepresentant: "",
    secteursActivite: "",
    domaineAutre: "",
    autresDomaines: "",
    domainesActivite: [],
  });
  const [profileData, setProfileData] = useState({
    nom: "SARL TechBat",
    siret: "12345678901234",
    adresse: "123 Avenue des Entrepreneurs",
    email: "contact@techbat.fr",
    telephone: "0123456789",
    nomRepresentant: "Dupont",
    prenomRepresentant: "Jean",
    secteursActivite: "Bâtiment",
    domainesActivite: ["Construction neuve", "Rénovation"],
    autreDomaine: "",
  });
  const [filters, setFilters] = useState({
    domaine: "",
    dateDebut: "",
    dateFin: "",
  });

  const entreprises = [
    { id: 1, nom: "SARL TechBat" },
    { id: 2, nom: "Construction Plus" },
    { id: 3, nom: "Eco Habitat" },
  ];

  const publications = [
    {
      id: 1,
      date: "2025-06-15",
      titre: "Construction école primaire - Ville de Lyon",
      echeance: "2025-07-30",
      domaine: "Construction neuve",
    },
    {
      id: 2,
      date: "2025-06-14",
      titre: "Rénovation énergétique bâtiments publics",
      echeance: "2025-07-25",
      domaine: "Rénovation",
    },
    {
      id: 3,
      date: "2025-06-13",
      titre: "Travaux voirie quartier centre-ville",
      echeance: "2025-08-20",
      domaine: "Génie civil",
    },
  ];

  const alertes = [
    {
      id: 1,
      titre: "Nouvel appel d'offres correspondant à vos critères",
      date: "2025-06-16",
    },
    {
      id: 2,
      titre: "Résultat publié pour consultation précédente",
      date: "2025-06-15",
    },
  ];

  const domainesActivite = [
    "Construction neuve",
    "Rénovation",
    "Génie civil",
    "Électricité",
    "Plomberie",
    "Isolation thermique",
  ];

  const secteursActivite = [
    "Bâtiment",
    "Travaux Publics",
    "Génie Civil",
    "Infrastructure",
    "Environnement",
    "Transport",
  ];

  const filteredPublications = publications.filter((pub) => {
    if (filters.domaine && pub.domaine !== filters.domaine) return false;
    if (filters.dateDebut && pub.date < filters.dateDebut) return false;
    if (filters.dateFin && pub.date > filters.dateFin) return false;
    return true;
  });

  const renderMobileHeader = () => (
    <header className="mobile-header">
      <button className="btn-menu" onClick={() => setSidebarOpen(true)}>
        ☰
      </button>
      <h4>Dashboard</h4>
    </header>
  );

  const renderSidebar = () => (
    <>
      <div className={`sidebar${sidebarOpen ? " show" : ""}`}>
        <div className="sidebar-header">
          <h4>Entreprises</h4>
          <button
            className="btn-close-sidebar"
            onClick={() => setSidebarOpen(false)}
          >
            ×
          </button>
        </div>
        <div className="sidebar-content">
          <select
            className="sidebar-select"
            value={selectedEntreprise}
            onChange={(e) => setSelectedEntreprise(e.target.value)}
          >
            <option value="">Sélectionnez</option>
            {entreprises.map((e) => (
              <option key={e.id} value={e.nom}>
                {e.nom}
              </option>
            ))}
          </select>
          <ul className="sidebar-nav">
            <li>
              <a
                href="#"
                className={`nav-link${
                  activeSection === "accueil" ? " active" : ""
                }`}
                onClick={() => {
                  setActiveSection("accueil");
                  setSidebarOpen(false);
                }}
              >
                Accueil
              </a>
            </li>
            <li>
              <a
                href="#"
                className={`nav-link${
                  activeSection === "veille" ? " active" : ""
                }`}
                onClick={() => {
                  setActiveSection("veille");
                  setSidebarOpen(false);
                }}
              >
                Veille
              </a>
            </li>
            <li>
              <a
                href="#"
                className={`nav-link${
                  activeSection === "alertes" ? " active" : ""
                }`}
                onClick={() => {
                  setActiveSection("alertes");
                  setSidebarOpen(false);
                }}
              >
                Alertes
              </a>
            </li>
            <li>
              <a
                href="#"
                className={`nav-link${
                  activeSection === "profil" ? " active" : ""
                }`}
                onClick={() => {
                  setActiveSection("profil");
                  setSidebarOpen(false);
                }}
              >
                Profil
              </a>
            </li>
          </ul>
          <button
            className="btn-cta"
            onClick={() => setShowAddEntrepriseModal(true)}
          >
            + Ajouter entreprise
          </button>
        </div>
      </div>
      <div
        className={`sidebar-overlay${sidebarOpen ? " show" : ""}`}
        onClick={() => setSidebarOpen(false)}
      />
    </>
  );

  const renderAccueil = () => (
    <div className="main-content">
      <div className="content-header">
        <h2>Bienvenue sur votre tableau de bord</h2>
      </div>
      <div className="row">
        <div className="col-md-4">
          <div className="card kpi-card">
            <div className="card-body">
              <h3 className="card-title">12</h3>
              <p className="card-text">Appels d'offres</p>
            </div>
          </div>
        </div>
        <div className="col-md-4">
          <div className="card kpi-card">
            <div className="card-body">
              <h3 className="card-title">5</h3>
              <p className="card-text">Alertes récentes</p>
            </div>
          </div>
        </div>
        <div className="col-md-4">
          <div className="card kpi-card">
            <div className="card-body">
              <h3 className="card-title">3</h3>
              <p className="card-text">Entreprises suivies</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderVeille = () => (
    <div className="main-content">
      <div className="content-header">
        <h2>Veille des appels d'offres</h2>
      </div>
      <div className="d-flex mb-3 gap-3">
        <select
          className="form-select"
          value={filters.domaine}
          onChange={(e) => setFilters({ ...filters, domaine: e.target.value })}
        >
          <option value="">Tous domaines</option>
          {domainesActivite.map((d) => (
            <option key={d} value={d}>
              {d}
            </option>
          ))}
        </select>
        <input
          type="date"
          className="form-control"
          value={filters.dateDebut}
          onChange={(e) =>
            setFilters({ ...filters, dateDebut: e.target.value })
          }
        />
        <input
          type="date"
          className="form-control"
          value={filters.dateFin}
          onChange={(e) => setFilters({ ...filters, dateFin: e.target.value })}
        />
        <button className="btn btn-cta" onClick={() => {}}>
          Filtrer
        </button>
      </div>
      <div className="table-responsive">
        <table className="table table-hover">
          <thead>
            <tr>
              <th>Date</th>
              <th>Titre</th>
              <th>Échéance</th>
              <th>Domaine</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {filteredPublications.map((pub) => (
              <tr key={pub.id}>
                <td>{pub.date}</td>
                <td>{pub.titre}</td>
                <td>{pub.echeance}</td>
                <td>{pub.domaine}</td>
                <td>
                  <button
                    className="btn btn-sm btn-cta"
                    onClick={() => {
                      setSelectedDocument(pub);
                      setShowModal(true);
                    }}
                  >
                    Voir
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  const renderAlertes = () => (
    <div className="main-content">
      <div className="content-header">
        <h2>Alertes</h2>
      </div>
      <ul className="list-group">
        {alertes.map((alerte) => (
          <li
            key={alerte.id}
            className="list-group-item d-flex justify-content-between align-items-center"
          >
            {alerte.titre}
            <span className="badge">{alerte.date}</span>
          </li>
        ))}
      </ul>
    </div>
  );

  const renderProfil = () => (
    <div className="main-content">
      <div className="content-header">
        <h2>Mon profil entreprise</h2>
      </div>
      <form onSubmit={(e) => e.preventDefault()}>
        <div className="mb-3">
          <label className="form-label">Nom</label>
          <input
            type="text"
            className="form-control"
            value={profileData.nom}
            onChange={(e) =>
              setProfileData({ ...profileData, nom: e.target.value })
            }
          />
        </div>
        <div className="mb-3">
          <label className="form-label">SIRET</label>
          <input
            type="text"
            className="form-control"
            value={profileData.siret}
            onChange={(e) =>
              setProfileData({ ...profileData, siret: e.target.value })
            }
          />
        </div>
        <div className="mb-3">
          <label className="form-label">Adresse</label>
          <input
            type="text"
            className="form-control"
            value={profileData.adresse}
            onChange={(e) =>
              setProfileData({ ...profileData, adresse: e.target.value })
            }
          />
        </div>
        <div className="mb-3">
          <label className="form-label">Email</label>
          <input
            type="email"
            className="form-control"
            value={profileData.email}
            onChange={(e) =>
              setProfileData({ ...profileData, email: e.target.value })
            }
          />
        </div>
        <div className="mb-3">
          <label className="form-label">Téléphone</label>
          <input
            type="text"
            className="form-control"
            value={profileData.telephone}
            onChange={(e) =>
              setProfileData({ ...profileData, telephone: e.target.value })
            }
          />
        </div>
        <div className="mb-3">
          <label className="form-label">Secteur d’activité</label>
          <select
            className="form-select"
            value={profileData.secteursActivite}
            onChange={(e) =>
              setProfileData({
                ...profileData,
                secteursActivite: e.target.value,
              })
            }
          >
            {secteursActivite.map((s) => (
              <option key={s} value={s}>
                {s}
              </option>
            ))}
          </select>
        </div>
        <div className="mb-3">
          <label className="form-label">Domaines d’activité</label>
          {domainesActivite.map((d) => (
            <div key={d} className="form-check">
              <input
                className="form-check-input"
                type="checkbox"
                checked={profileData.domainesActivite.includes(d)}
                onChange={() => {
                  const list = profileData.domainesActivite.includes(d)
                    ? profileData.domainesActivite.filter((x) => x !== d)
                    : [...profileData.domainesActivite, d];
                  setProfileData({ ...profileData, domainesActivite: list });
                }}
              />
              <label className="form-check-label">{d}</label>
            </div>
          ))}
          <div className="form-check mt-2">
            <input
              className="form-check-input"
              type="checkbox"
              checked={!!profileData.autreDomaine}
              onChange={(e) =>
                setProfileData({
                  ...profileData,
                  autreDomaine: e.target.checked ? "" : "",
                })
              }
            />
            <label className="form-check-label">Autre domaine</label>
            {profileData.autreDomaine !== null && (
              <input
                type="text"
                className="form-control mt-1"
                placeholder="Précisez"
                value={profileData.autreDomaine}
                onChange={(e) =>
                  setProfileData({
                    ...profileData,
                    autreDomaine: e.target.value,
                  })
                }
              />
            )}
          </div>
        </div>
        <button
          className="btn btn-cta"
          onClick={() => alert("Profil mis à jour")}
        >
          Mettre à jour
        </button>
      </form>
    </div>
  );

  const renderModal = () => (
    <div className="modal fade show" style={{ display: "block" }}>
      <div className="modal-dialog">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">{selectedDocument.titre}</h5>
            <button className="btn-close" onClick={() => setShowModal(false)} />
          </div>
          <div className="modal-body">
            <p>Date : {selectedDocument.date}</p>
            <p>Échéance : {selectedDocument.echeance}</p>
            <p>Domaine : {selectedDocument.domaine}</p>
          </div>
          <div className="modal-footer">
            <button className="btn btn-cta" onClick={() => setShowModal(false)}>
              Fermer
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderAddEntrepriseModal = () => (
    <div className="modal fade show" style={{ display: "block" }}>
      <div className="modal-dialog">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">Ajouter une entreprise</h5>
            <button
              className="btn-close"
              onClick={() => setShowAddEntrepriseModal(false)}
            />
          </div>
          <div className="modal-body">
            <form
              onSubmit={(e) => {
                e.preventDefault();
                setShowAddEntrepriseModal(false);
              }}
            >
              <div className="mb-3">
                <label className="form-label">Nom</label>
                <input
                  type="text"
                  className="form-control"
                  value={addEntrepriseData.nom}
                  onChange={(e) =>
                    setAddEntrepriseData({
                      ...addEntrepriseData,
                      nom: e.target.value,
                    })
                  }
                  required
                />
              </div>
              <div className="mb-3">
                <label className="form-label">SIRET</label>
                <input
                  type="text"
                  className="form-control"
                  value={addEntrepriseData.siret}
                  onChange={(e) =>
                    setAddEntrepriseData({
                      ...addEntrepriseData,
                      siret: e.target.value,
                    })
                  }
                  required
                />
              </div>
              <div className="mb-3">
                <label className="form-label">Téléphone</label>
                <input
                  type="text"
                  className="form-control"
                  value={addEntrepriseData.telephone}
                  onChange={(e) =>
                    setAddEntrepriseData({
                      ...addEntrepriseData,
                      telephone: e.target.value,
                    })
                  }
                />
              </div>
              <div className="mb-3">
                <label className="form-label">Email</label>
                <input
                  type="email"
                  className="form-control"
                  value={addEntrepriseData.email}
                  onChange={(e) =>
                    setAddEntrepriseData({
                      ...addEntrepriseData,
                      email: e.target.value,
                    })
                  }
                />
              </div>
              <div className="mb-3">
                <label className="form-label">Secteur d’activité</label>
                <select
                  className="form-select"
                  value={addEntrepriseData.secteursActivite}
                  onChange={(e) =>
                    setAddEntrepriseData({
                      ...addEntrepriseData,
                      secteursActivite: e.target.value,
                    })
                  }
                >
                  <option value="">Sélectionnez</option>
                  {secteursActivite.map((s) => (
                    <option key={s} value={s}>
                      {s}
                    </option>
                  ))}
                </select>
              </div>
              <div className="mb-3">
                <label className="form-label">Domaines d’activité</label>
                {domainesActivite.map((d) => (
                  <div key={d} className="form-check">
                    <input
                      className="form-check-input"
                      type="checkbox"
                      checked={addEntrepriseData.domainesActivite.includes(d)}
                      onChange={() => {
                        const list =
                          addEntrepriseData.domainesActivite.includes(d)
                            ? addEntrepriseData.domainesActivite.filter(
                                (x) => x !== d
                              )
                            : [...addEntrepriseData.domainesActivite, d];
                        setAddEntrepriseData({
                          ...addEntrepriseData,
                          domainesActivite: list,
                        });
                      }}
                    />
                    <label className="form-check-label">{d}</label>
                  </div>
                ))}
                <div className="form-check mt-2">
                  <input
                    className="form-check-input"
                    type="checkbox"
                    checked={!!addEntrepriseData.domaineAutre}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        domaineAutre: e.target.checked ? "" : "",
                      })
                    }
                  />
                  <label className="form-check-label">Autre domaine</label>
                  {addEntrepriseData.domaineAutre !== null && (
                    <input
                      type="text"
                      className="form-control mt-1"
                      placeholder="Précisez"
                      value={addEntrepriseData.autresDomaines}
                      onChange={(e) =>
                        setAddEntrepriseData({
                          ...addEntrepriseData,
                          autresDomaines: e.target.value,
                        })
                      }
                    />
                  )}
                </div>
              </div>
              <button className="btn btn-cta" type="submit">
                Enregistrer
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );

  const renderContent = () => {
    switch (activeSection) {
      case "veille":
        return renderVeille();
      case "alertes":
        return renderAlertes();
      case "profil":
        return renderProfil();
      default:
        return renderAccueil();
    }
  };

  return (
    <>
      <div className="dashboard-container">
        {renderMobileHeader()}
        {renderSidebar()}
        <div className="main-wrapper">{renderContent()}</div>
        {showModal && renderModal()}
        {showAddEntrepriseModal && renderAddEntrepriseModal()}
      </div>
    </>
  );
};

export default Dashboard;
